using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace Dafeiyu.Tests
{
    public static class TerminalUiTests
    {
        static int checks;static Application app;static PetWindow pet;
        static void Check(bool ok,string text){if(!ok)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
        static IEnumerable<T> All<T>(DependencyObject p)where T:DependencyObject{if(p is T)yield return(T)p;for(int i=0;i<VisualTreeHelper.GetChildrenCount(p);i++)foreach(var item in All<T>(VisualTreeHelper.GetChild(p,i)))yield return item;}
        static async Task Ready(TerminalPane pane){var task=pane.Ready;if(await Task.WhenAny(task,Task.Delay(30000))!=task)throw new Exception("Terminal did not start in time");await task;if(!pane.IsRunning)Console.Error.WriteLine(pane.StartupError);Check(pane.IsRunning,"terminal tab has a real running shell");}
        static string ScreenScript="(()=>{let s='';for(let i=0;i<term.buffer.active.length;i++){s+=term.buffer.active.getLine(i).translateToString()+'\\n';}return s;})()";
        static async Task Contains(TerminalPane pane,string expected){for(int i=0;i<100;i++){string text=await pane.EvaluateAsync(ScreenScript);if(text.Contains(expected))return;await Task.Delay(100);}throw new Exception("Terminal never displayed "+expected+": "+await pane.EvaluateAsync(ScreenScript));}
        static async Task Run(bool native)
        {
            string root=Path.Combine(Directory.GetCurrentDirectory(),"work","permissions","terminal-ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string first=Path.Combine(root,"说明.md"),second=Path.Combine(root,"Demo.cs");File.WriteAllText(first,"# 文件预览\n\n文件与终端共用标签区。");File.WriteAllText(second,"class Demo {}\n");
            var cfg=new PetSettings{AutoUpdate=false,GreetingEnabled=false,ShowPredictedMessages=false,ReadReplies=false,OnboardingState="completed",AgentWorkspace=root};foreach(string key in cfg.Hotkeys.Keys.ToArray())cfg.Hotkeys[key]="";pet=new PetWindow(null,cfg,new SettingsStore(Path.Combine(root,"data","settings.json")),null);var full=new ChatWindow(pet);full.Width=1500;full.Show();await Task.Delay(150);
            var add=All<Button>(full).Single(b=>b.Name=="AddAttachment");add.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var open=add.ContextMenu.Items.OfType<MenuItem>().Single(m=>m.Name=="OpenTerminal");Check((string)open.Header=="打开终端"&&open.Icon!=null,"full composer plus menu includes terminal with matching icon");add.ContextMenu.IsOpen=false;
            var quick=new QuickChatWindow(pet);quick.Show();await Task.Delay(100);var quickAdd=All<Button>(quick).Single(b=>b.Name=="AddAttachment");quickAdd.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!quickAdd.ContextMenu.Items.OfType<MenuItem>().Any(m=>m.Name=="OpenTerminal"),"quick personal chat remains free of work terminal controls");quickAdd.ContextMenu.IsOpen=false;quick.Close();
            full.OpenFilePreview(first);full.OpenFilePreview(second);await Task.Delay(100);var area=All<PreviewWorkspace>(full).Single();Check(area.Count==2&&((FilePreviewPane)area.Selected).FilePath==second,"different output files open separate right-side tabs");full.OpenFilePreview(first);Check(area.Count==2&&((FilePreviewPane)area.Selected).FilePath==first,"reopening same file selects its existing tab");area.Close(area.Selected);Check(area.Count==1&&((FilePreviewPane)area.Selected).FilePath==second,"closing active tab selects adjacent file");
            if(native)
            {
                open.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));await Task.Delay(150);var one=(TerminalPane)area.Selected;await Ready(one);await Contains(one,"PS ");
                await one.EvaluateAsync("term.input(\"$global:deskpetTerminalUi='first'; [Console]::WriteLine([string]::Concat('中文','交互成功'))\\r\",true);true");await Contains(one,"中文交互成功");Check(true,"xterm input bridge executes real PowerShell and renders Chinese");
                All<Button>(area).Single(b=>b.Name=="NewPreviewTab").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(100);All<Button>(area).Single(b=>b.Name=="NewTabTerminal").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(150);var two=(TerminalPane)area.Selected;await Ready(two);Check(area.Count==3&&!ReferenceEquals(one,two),"plus in preview creates an independent second terminal tab");
                await two.EvaluateAsync("term.input(\"[Console]::WriteLine('STATE='+[string]$global:deskpetTerminalUi)\\r\",true);true");await Contains(two,"STATE=");Check(!(await two.EvaluateAsync(ScreenScript)).Contains("STATE=first"),"terminal tabs do not share shell variables");
                full.ToggleFullTabView();await Task.Delay(120);Check(area.HasConversation&&ReferenceEquals(area.Selected,two)&&one.IsRunning&&two.IsRunning,"manual full tab mode preserves both native terminal sessions and selection");area.SelectConversation();All<Button>(full).Single(b=>b.Name=="ToggleSideTabs").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(80);All<Button>(full).Single(b=>b.Name=="ToggleSideTabs").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(100);Check(area.HasConversation&&!(area.Selected is TerminalPane)&&one.IsRunning&&two.IsRunning,"hiding and restoring full tabs preserves the pinned chat and both terminal processes");full.ToggleFullTabView();await Task.Delay(100);Check(!area.HasConversation&&ReferenceEquals(area.Selected,two),"returning from full chat restores the previously selected native terminal");await one.EvaluateAsync("term.input(\"[Console]::WriteLine('FULL_VIEW_OK='+[string]$global:deskpetTerminalUi)\\r\",true);true");await Contains(one,"FULL_VIEW_OK=first");Check(true,"terminal variables and actual execution survive full split and hidden layouts");
                full.Width=850;await Task.Delay(150);Check(two.IsRunning&&area.IsVisible&&!full.OwnedWindows.OfType<Window>().Any(w=>w.Content is PreviewWorkspace),"narrow terminal stays in the main window with its process running");All<Button>(full).Single(b=>b.Name=="BackToConversation").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(100);Check(!area.IsVisible&&two.IsRunning,"returning to conversation hides side pane without stopping terminal");full.Width=1500;await Task.Delay(150);await two.EvaluateAsync("term.input(\"[Console]::WriteLine([string]::Concat('AFTER_','REDOCK'))\\r\",true);true");await Contains(two,"AFTER_REDOCK");Check(true,"terminal remains interactive after returning to dock");
                using(var stream=File.Create(Path.Combine("work","permissions","terminal-tabs.png")))await two.CaptureAsync(stream);
                area.Close(two);Check(!two.IsRunning&&one.IsRunning&&area.Count==2,"closing one terminal stops it and preserves sibling session");full.OpenFilePreview(first);Check(one.IsRunning&&area.Selected is FilePreviewPane,"file preview and running terminal coexist across tab selection");area.Close(one);Check(!one.IsRunning,"closing background terminal releases its process");
                pet.Settings.AgentApprovalMode=AgentApprovalMode.Ask;pet.Settings.AgentSandboxEnabled=true;full.OpenTerminal();await Task.Delay(120);var isolated=(TerminalPane)area.Selected;await Ready(isolated);Check(isolated.Sandboxed,"new terminal actually starts with selected workspace sandbox");await isolated.EvaluateAsync("term.input(\"Set-Content -LiteralPath 'ui-sandbox.txt' -Value 'sandbox-ui'\\r\",true);true");for(int i=0;i<60&&!File.Exists(Path.Combine(root,"ui-sandbox.txt"));i++)await Task.Delay(100);Check(File.Exists(Path.Combine(root,"ui-sandbox.txt"))&&File.ReadAllText(Path.Combine(root,"ui-sandbox.txt")).Contains("sandbox-ui"),"sandbox terminal input bridge writes inside its real project");pet.Settings.AgentSandboxEnabled=false;Check(isolated.Sandboxed,"changing defaults does not silently loosen an existing terminal");area.Close(isolated);
            }
            full.Close();Console.WriteLine("Terminal UI tests: "+checks+" passed"+(native?" (native ConPTY + WebView2)":" (layout/menu only)"));
        }
        [STAThread]public static int Main(string[] args){app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};int result=1;app.Dispatcher.BeginInvoke(new Action(async delegate{try{await Run(args.Contains("--native"));result=0;}catch(Exception e){Console.Error.WriteLine(e);}finally{foreach(var window in app.Windows.OfType<Window>().ToArray())window.Close();if(pet!=null)pet.Close();app.Shutdown();}}));app.Run();return result;}
    }
}
